  evidence.checkpoint={partyId:id,stage:n,originalStartedAt:p.state.startedAt,originalEndsAt:p.state.endsAt,settledAt:after.qaClock.now,result:p.state.results[n-1],freshRewards:fresh,allRewards:rewards(after,id),actorSHA256:sha(JSON.stringify(p.state.actors)),foregroundBefore,foregroundAfter:fg?foregroundProof(after,fg):null};persist('original checkpoint committed and captured; never replay');
  assert.equal(p.state.results.length,n);assert.equal(p.state.endsAt-p.state.startedAt,43200000);assert.equal(after.qaClock.now,p.state.startedAt+n*7200000);assert.equal(sha(JSON.stringify(p.state.actors)),originalActorHash,'departure snapshot not rerolled');assert.deepEqual(p.state.results.slice(0,n-1),oldResults,'previous results retained');assert.deepEqual(rewards(after,id).filter(x=>x.stage<n-1),oldRewards,'previous rewards retained');assert.equal(fresh.length,active.length);
